function init() {
  hydrateImportedProductCatalog();
  bindEvents();
  resetQuoteVersions();
  renderAll();
  loadRuntimeData();
  loadAiSettings();
}

function bindEvents() {
  bindDelegatedActions();
  $$(".module").forEach((btn) => btn.addEventListener("click", () => switchModule(btn.dataset.module)));
  $$(".stepper a").forEach((a) => a.addEventListener("click", () => {
    $$(".stepper a").forEach((x) => x.classList.remove("active"));
    a.classList.add("active");
  }));
  on("#newProject", "click", resetProject);
  on("#newProjectFromDashboard", "click", resetProject);
  $("#backToProjects").addEventListener("click", showProjectDashboard);
  on("#xiaoyiLauncher", "click", openXiaoyi);
  on("#closeXiaoyi", "click", closeXiaoyi);
  on("#submitQuote", "click", () => {
    showWorkbenchSection("q-proposal");
    if (!$("#proposalContent")?.innerHTML.trim()) handleBuildProposal();
  });
  on("#confirmProposal", "click", confirmProposal);
  on("#addAssetUrl", "click", addProposalAssetFromUrl);
  on("#assetUploadInput", "change", handleProposalAssetUpload);
  on("#image2Placeholder", "click", () => alert("Image2 / 图像模型补图为后续预留入口。真实酒店图片不会自动用 AI 生成进入客户报价单。"));
  on("#saveAiSettings", "click", saveAiSettings);
  on("#testAiSettings", "click", testAiSettings);
  on("#clearAiSettings", "click", clearAiSettings);
  on("#agentRecognizeFromEditor", "click", () => {
    openXiaoyi();
    agentRecognizeDemand();
  });
  $("#periodFilter").addEventListener("change", (event) => {
    state.period = event.target.value;
    renderProjectDashboard();
  });
  $("#projectSearch").addEventListener("input", (event) => {
    state.projectFilters.search = event.target.value.trim();
    renderProjectDashboard();
  });
  $("#projectStatusFilter").addEventListener("change", (event) => {
    state.projectFilters.status = event.target.value;
    renderProjectDashboard();
  });
  $("#projectUserTypeFilter").addEventListener("change", (event) => {
    state.projectFilters.userType = event.target.value;
    renderProjectDashboard();
  });
  $("#projectCountryFilter").addEventListener("input", (event) => {
    state.projectFilters.country = event.target.value.trim();
    renderProjectDashboard();
  });
  $("#clearProjectFilters").addEventListener("click", clearProjectFilters);
  on("#syncFeishuProducts", "click", syncFeishuProducts);
  on("#addResourceItem", "click", addResourceItem);
  on("#closeProductModal", "click", closeProductModal);
  on("#cancelProductModal", "click", closeProductModal);
  on("#saveProductModal", "click", saveProductFromModal);
  on("#addSupplier", "click", addSupplier);
  on("#resourceSearch", "input", (event) => { state.resourceFilters.search = event.target.value.trim(); renderResourceLibrary(); });
  on("#resourceTypeFilter", "change", (event) => { state.resourceFilters.type = event.target.value; renderResourceLibrary(); });
  on("#resourceCityFilter", "input", (event) => { state.resourceFilters.city = event.target.value.trim(); renderResourceLibrary(); });
  on("#resourceSupplierFilter", "change", (event) => { state.resourceFilters.supplierId = event.target.value; renderResourceLibrary(); });
  on("#resourceStatusFilter", "change", (event) => { state.resourceFilters.status = event.target.value; renderResourceLibrary(); });
  on("#supplierSearch", "input", (event) => { state.supplierFilters.search = event.target.value.trim(); renderSupplierManagement(); });
  on("#supplierCategoryFilter", "change", (event) => { state.supplierFilters.category = event.target.value; renderSupplierManagement(); });
  on("#supplierStatusFilter", "change", (event) => { state.supplierFilters.status = event.target.value; renderSupplierManagement(); });
  on("#loadSample", "click", loadSample);
  on("#saveVersion", "click", handleSaveVersion);
  on("#loadHistory", "click", handleLoadHistory);
  on("#generateItinerary", "click", handleGenerateItinerary);
  on("#aiImportItinerary", "click", handleAiImportItinerary);
  on("#importItineraryText", "click", importItineraryText);
  on("#addDay", "click", handleAddDay);
  on("#addRoomTypeRow", "click", addRoomTypeRow);
  on("#newQuoteVersion", "click", newQuoteVersion);
  on("#buildQuote", "click", buildQuote);
  on("#refreshSummary", "click", renderSummary);
  on("#buildProposal", "click", handleBuildProposal);
  on("#editProposal", "click", toggleProposalEdit);
  on("#exportPdf", "click", handleExportPdf);
  on("#exportImage", "click", handleExportImage);
  on("#convertToOrder", "click", convertToOrder);
  on("#agentRecognizeDemand", "click", agentRecognizeDemand);
  on("#agentApplyCustomer", "click", agentApplyCustomer);
  on("#agentCheckMissing", "click", agentCheckMissing);
  on("#agentFollowQuestions", "click", agentFollowQuestions);
  on("#agentGenerateRoute", "click", agentGenerateRoute);
  on("#agentOptimizeRoute", "click", agentOptimizeRoute);
  on("#agentConfirmRoute", "click", agentConfirmRoute);
  on("#agentExtractQuoteItems", "click", agentExtractQuoteItems);
  on("#agentApplyQuoteItems", "click", agentApplyQuoteItems);
  on("#agentRecalculateQuote", "click", agentRecalculateQuote);
  on("#agentCheckCosts", "click", agentCheckCosts);
  on("#agentBuildCustomerProposal", "click", agentBuildCustomerProposal);
  on("#agentCheckEnglish", "click", agentCheckEnglish);
  on("#agentSaveQuoteVersion", "click", agentSaveQuoteVersion);

  [
    "clientName", "actualCustomerName", "clientAccount", "clientType", "clientCountry", "source", "owner", "followStatus", "budgetRange", "languageNeed", "hotelPreference", "mealPreference", "aiNotes", "opNotes", "startDate", "serviceDays", "adults", "children",
    "cities", "svcVehicle", "svcTickets", "svcGuide", "svcHotel", "svcTraffic", "svcMeals", "svcOther",
    "transferNeed", "transferVehicleType", "charterNeed", "charterVehicleType", "guideLang", "hotelLevel",
    "rooms", "hotelBreakfast", "trafficType", "mealBreakfast", "mealLunch", "mealDinner",
    "otherInsurance", "otherHeadset", "otherWater", "otherGift",
  ].forEach((id) => {
    $(`#${id}`).addEventListener("input", () => {
      updateProjectTitle();
      renderQuoteTabs();
      renderIncludeButtons();
      renderRoomTypes();
      invalidateProposalConfirmation();
      renderWorkbenchOverview();
      autoBuildQuote();
      rebuildProposalIfNeeded();
    });
  });

  ["startDate", "serviceDays"].forEach((id) => {
    $(`#${id}`).addEventListener("change", syncItineraryToDemand);
  });

  $$(".include-toggle").forEach((btn) => btn.addEventListener("click", () => {
    const input = $(`#${btn.dataset.include}`);
    input.checked = !input.checked;
    renderIncludeButtons();
    renderQuoteTabs();
    invalidateProposalConfirmation();
    renderWorkbenchOverview();
    autoBuildQuote();
  }));

  ["grossMargin", "currency"].forEach((id) => {
    $(`#${id}`).addEventListener("input", () => {
      renderRateCard();
      renderQuoteTable();
      renderSummary();
      invalidateProposalConfirmation();
      renderWorkbenchOverview();
    });
  });
  $("#quoteVersion").addEventListener("change", (event) => {
    state.activeQuote = Number(event.target.value);
    renderQuoteTable();
    renderSummary();
    renderArchive();
  });
  $("#outputLang").addEventListener("change", rebuildProposalIfNeeded);
  ["priceTotal", "priceAverage", "priceItemized", "proposalWatermark", "contactWhatsapp", "contactWechat", "contactEmail", "contactWhatsappValue", "contactWechatValue"].forEach((id) => {
    $(`#${id}`).addEventListener("change", () => {
      rebuildProposalIfNeeded();
    });
    $(`#${id}`).addEventListener("input", rebuildProposalIfNeeded);
  });

  $$("[data-workbench-edit]").forEach((btn) => btn.addEventListener("click", () => showWorkbenchSection(btn.dataset.workbenchEdit)));
  $$("[data-workbench-home]").forEach((btn) => btn.addEventListener("click", showWorkbenchHome));
  $$("[data-workbench-save]").forEach((btn) => btn.addEventListener("click", () => {
    updateCurrentProject();
    showWorkbenchHome();
  }));
  $$("#quoteStepper [data-step-target]").forEach((btn) => btn.addEventListener("click", () => showWorkbenchSection(btn.dataset.stepTarget)));
}

function bindDelegatedActions() {
  if (document.body.dataset.delegatedActionsBound) return;
  document.body.dataset.delegatedActionsBound = "true";
  document.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    const actions = {
      generateItinerary: handleGenerateItinerary,
      aiImportItinerary: handleAiImportItinerary,
      loadHistory: handleLoadHistory,
      addDay: handleAddDay,
      buildProposal: handleBuildProposal,
      exportPdf: handleExportPdf,
      exportImage: handleExportImage,
      saveVersion: handleSaveVersion,
      agentRecognizeDemand,
      agentApplyCustomer,
      agentCheckMissing,
      agentFollowQuestions,
      agentGenerateRoute,
      agentOptimizeRoute,
      agentConfirmRoute,
      agentExtractQuoteItems,
      agentApplyQuoteItems,
      agentRecalculateQuote,
      agentCheckCosts,
      agentBuildCustomerProposal,
      agentCheckEnglish,
      agentSaveQuoteVersion,
      confirmProposal,
    };
    const action = actions[button.id];
    if (button.dataset.agentApply) {
      event.preventDefault();
      event.stopPropagation();
      applyCurrentAgentPending();
      return;
    }
    if (button.dataset.agentIgnore) {
      event.preventDefault();
      event.stopPropagation();
      setAgentPending("message", { title: "已忽略 AI 建议", body: "未对正式页面数据做任何修改。" });
      return;
    }
    if (!action) return;
    event.preventDefault();
    event.stopPropagation();
    action();
  }, true);
}

function applyCurrentAgentPending() {
  const type = state.agent.pendingType;
  if (type === "customer") return agentApplyCustomer();
  if (type === "route") return agentConfirmRoute();
  if (type === "quoteItems") return agentApplyQuoteItems();
  if (type === "customerProposal") {
    applyCustomerProposal(state.agent.pendingData);
    return setAgentPending("message", { title: "已应用客户版报价文案", body: "客户提案预览已更新，导出前请人工确认方案。" });
  }
  return setAgentPending("message", { title: "当前建议无需应用", body: "这是检查或提示信息，不会写入正式页面字段。" });
}

