  const conversion = mine.length ? Math.round((mine.filter((project) => project.status.includes("已成交") || project.status.includes("已操作") || project.status.includes("已服务")).length / mine.length) * 100) : 0;
  const previousAmount = previous.reduce((sum, project) => sum + number(project.amount), 0);
