function renderProjectStatusFilter() {
  $("#projectStatusFilter").innerHTML = `<option value="">全部状态</option>${projectStatuses.map((status) => `<option ${state.projectFilters.status === status ? "selected" : ""}>${status}</option>`).join("")}`;
  $("#projectSearch").value = state.projectFilters.search;
  $("#projectUserTypeFilter").value = state.projectFilters.userType;
  $("#projectCountryFilter").value = state.projectFilters.country;
}

function clearProjectFilters() {
  state.projectFilters = { status: "", search: "", userType: "", country: "" };
  renderProjectDashboard();
}

function filteredProjects(projects) {
  const f = state.projectFilters;
  return projects.filter((project) => {
    const haystack = [project.name, project.account, project.country, project.cities, project.source].join(" ").toLowerCase();
    return (!f.status || project.status === f.status)
      && (!f.userType || project.userType === f.userType)
      && (!f.country || String(project.country || "").includes(f.country))
      && (!f.search || haystack.includes(f.search.toLowerCase()));
  });
}

function sortedProjects(projects) {
  const { key, dir } = state.projectSort;
  const sign = dir === "asc" ? 1 : -1;
  return projects.slice().sort((a, b) => {
    if (key === "statusUpdatedDate" || key === "serviceStart") return (dateValue(a[key]) - dateValue(b[key])) * sign;
    return (number(a[key]) - number(b[key])) * sign;
  });
}

function sortIcon(key) {
  if (state.projectSort.key !== key) return "↕";
  return state.projectSort.dir === "asc" ? "↑" : "↓";
}

function periodProjects() {
  const range = periodRange(state.period);
  return state.projects.filter((project) => inDateRange(project.createdDate || project.statusUpdatedDate, range.start, range.end));
}

function previousPeriodProjects() {
  const range = periodRange(state.period);
  const days = Math.max(Math.round((dateValue(range.end) - dateValue(range.start)) / 86400000) + 1, 1);
  const prevEnd = addDays(range.start, -1);
  const prevStart = addDays(prevEnd, -(days - 1));
  return state.projects.filter((project) => inDateRange(project.createdDate || project.statusUpdatedDate, prevStart, prevEnd));
}

function periodRange(period) {
  const today = "2026-06-18";
  if (period === "today") return { start: today, end: today };
  if (period === "week") return { start: "2026-06-15", end: today };
  if (period === "month") return { start: "2026-06-01", end: today };
  return { start: addDays(today, -29), end: today };
}

function inDateRange(date, start, end) {
  const value = dateValue(date);
  return value >= dateValue(start) && value <= dateValue(end);
}

function dateValue(date) {
  return Date.parse(`${date || "1970-01-01"}T00:00:00Z`);
}

function formatDiff(value, isMoney, isPercent = false) {
  const numeric = number(value);
  const prefix = numeric > 0 ? "+" : "";
  if (isPercent) return `${prefix}${numeric}%`;
  return isMoney ? `${prefix}${money(numeric)}` : `${prefix}${numeric}`;
}

