function productFilterOptions(category) {
  if (category === "线路产品") return { label: "产品类型", allLabel: "全部类型", values: unique(state.productCatalog.routes.map((item) => item.productType)) };
  if (category === "用车") return { label: "用车类型", allLabel: "全部类型", values: unique(state.productCatalog.vehicles.map((item) => item.vehicleType)) };
  if (category === "导游") return { label: "语种", allLabel: "全部语种", values: unique(state.productCatalog.guides.map((item) => item.language)) };
  if (category === "酒店") return { label: "酒店等级", allLabel: "全部等级", values: unique(state.productCatalog.hotels.map((item) => item.star)) };
  if (category === "餐") return { label: "是否清真", allLabel: "全部", values: ["是", "否"] };
  if (category === "景点门票") return { label: "景区类型", allLabel: "全部类型", values: unique(state.productCatalog.tickets.map((item) => item.type)) };
  return { label: "城市", allLabel: "全部城市", values: unique(productCatalogItems(category).map((item) => item.city)) };
}

function productCatalogItems(category) {
  const map = {
    线路产品: state.productCatalog.routes,
    用车: state.productCatalog.vehicles,
    特色体验: state.productCatalog.experiences,
    景点门票: state.productCatalog.tickets,
    导游: state.productCatalog.guides,
    酒店: state.productCatalog.hotels,
    餐: state.productCatalog.meals,
  };
  return map[category] || [];
}

const IMPORTED_PENDING_SUPPLIER = "飞书导入待绑定供应商";
const IMPORT_VALID_FROM = "2026-06-21";
const IMPORT_VALID_TO = "2027-12-31";

function hydrateImportedProductCatalog() {
  state.productCatalog.routes.forEach((route, index) => {
    route.routeProductId = route.routeProductId || `ROUTE-${route.code || String(index + 1).padStart(5, "0")}`;
    route.sourceProductId = route.routeProductId;
    route.projectId = "";
  });
  refreshQuoteResources();
}

async function loadRuntimeData() {
  try {
    const [attractions, vehicles, guides, hotels, transports, routes, pricingRules, profitStrategies] = await Promise.all([
      fetchJson("data/products/attractions.json"),
      fetchJson("data/products/vehicles.json"),
      fetchJson("data/products/guides.json"),
      fetchJson("data/products/hotels.json"),
      fetchJson("data/products/transports.json"),
      fetchJson("data/cases/historical-routes.json"),
      fetchJson("data/rules/pricing-rules.json"),
      fetchJson("data/rules/profit-strategies.json"),
    ]);
    mergeRuntimeProducts({ attractions, vehicles, guides, hotels, transports, routes, pricingRules, profitStrategies });
    state.runtimeData = { loaded: true, error: "" };
    refreshQuoteResources();
    renderResourceLibrary();
    renderQuoteTabs();
    renderQuoteTable();
    renderSummary();
    writeAcceptanceProbe();
  } catch (error) {
    state.runtimeData = { loaded: false, error: error.message || "本地数据加载失败" };
    console.warn("Runtime quote data load failed:", error);
  }
}

async function fetchJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url} ${response.status}`);
  return response.json();
}

function mergeRuntimeProducts(data) {
  appendUnique(state.productCatalog.tickets, (data.attractions || []).map(runtimeAttractionToTicket), "runtimeId");
  appendUnique(state.productCatalog.vehicles, (data.vehicles || []).map(runtimeVehicleToProduct), "runtimeId");
  appendUnique(state.productCatalog.guides, (data.guides || []).map(runtimeGuideToProduct), "runtimeId");
  appendUnique(state.productCatalog.hotels, (data.hotels || []).map(runtimeHotelToProduct), "runtimeId");
  state.productCatalog.transports = data.transports || [];
  appendRuntimeHistoricalRoutes(data.routes || []);
  state.pricingRules = data.pricingRules || {};
  state.profitStrategies = data.profitStrategies || [];
}

function appendUnique(target, items, key) {
  const existing = new Set(target.map((item) => item[key]).filter(Boolean));
  items.filter(Boolean).forEach((item) => {
    if (item[key] && existing.has(item[key])) return;
    target.push(item);
    if (item[key]) existing.add(item[key]);
  });
}

function runtimeAttractionToTicket(item) {
  return {
    runtimeId: item.id,
    city: item.city || "",
    scenicName: item.name_cn || item.name_en || "",
    ticketType: item.category || "景区门票",
    type: item.category || "景点门票",
    agencyAdult: valueOrEmpty(item.adult_price),
    agencyDiscount: valueOrEmpty(item.child_price),
    peakAdult: valueOrEmpty(item.adult_price),
    peakDiscount: valueOrEmpty(item.child_price),
    offAdult: valueOrEmpty(item.adult_price),
    offDiscount: valueOrEmpty(item.child_price),
    freePolicy: item.guide_ticket_free ? "导游免票" : "",
    remark: [item.requires_reservation ? `需提前${item.reservation_days_before || ""}天预约` : "", item.suitable_for].filter(Boolean).join("；"),
    supplierName: "清洗产品库",
    source: item.source || "本地清洗数据",
  };
}

function runtimeVehicleToProduct(item) {
  const model = item.seat_count ? `${item.seat_count}座车` : `${item.vehicle_type || "用车"}`;
  return {
    runtimeId: item.id,
    city: item.city || "",
    vehicleType: item.vehicle_type || "包车",
    route: item.vehicle_type || "市区包车",
    model,
    costPrice: valueOrEmpty(item.full_day_price || item.airport_transfer_price || item.half_day_price),
    salePrice: "",
    supplierName: "清洗产品库",
    source: item.source || "本地清洗数据",
  };
}

function runtimeGuideToProduct(item) {
  const language = Array.isArray(item.languages) ? item.languages.join("/") : (item.languages || "英语");
  return {
    runtimeId: item.id,
    city: item.city || "",
    language,
    lowSeasonCost: valueOrEmpty(item.full_day_price),
    highSeasonCost: valueOrEmpty(item.full_day_price),
    lowSeasonSale: "",
    highSeasonSale: "",
    needsTicket: item.has_license ? "有导游证" : "",
    supplierName: item.name_cn || "清洗导游库",
    source: item.source || "本地清洗数据",
  };
}

function runtimeHotelToProduct(item) {
  return {
    runtimeId: item.id,
    city: item.city || "",
    hotelName: item.name_cn || item.name_en || "",
    star: item.star_rating || "",
    roomType: item.room_type || "双床房",
    costPrice: valueOrEmpty(item.nightly_price),
    salePrice: "",
    breakfast: item.breakfast_included ? "含早" : "不含早",
    hasAgreement: item.cooperation_status || "",
    agreementFixed: "",
    supplierName: "清洗酒店库",
    source: item.source || "本地清洗数据",
  };
}

function appendRuntimeHistoricalRoutes(routes) {
  routes.forEach((item) => {
    if (historicalTrips.some((trip) => trip.id === item.id)) return;
    const days = (item.itinerary_summary || []).map((day) => ({
      city: day.city || "",
      overview: day.title || day.summary || "",
      detail: day.summary || day.title || "",
    }));
    historicalTrips.push({
      id: item.id,
      name: item.route_name || item.id,
      cities: item.cities || [],
      days,
    });
  });
}

function refreshQuoteResources() {
  state.quoteResources = generateQuoteResources();
  state.importQuality = buildImportQualityReport();
  return state.quoteResources;
}

function quoteResources() {
  if (!state.quoteResources?.length) refreshQuoteResources();
  return state.quoteResources;
}

function generateQuoteResources() {
  const resources = [];
  state.productCatalog.vehicles.forEach((item, index) => {
    resources.push(makeQuoteResource({
      id: `QR-VEH-${String(index + 1).padStart(5, "0")}`,
      type: "vehicle",
      city: item.city,
      name: `${item.route} ${item.model}`,
      unit: item.vehicleType?.includes("接送") ? "次" : "天",
      cost: valueOrEmpty(item.costPrice),
      salePrice: valueOrEmpty(item.salePrice),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `VEH-${index + 1}`,
      sourceCategory: "用车",
      status: item.costPrice === "" || item.costPrice == null ? "待补成本" : "可用",
      tags: [item.vehicleType, item.route, item.model, normalizeVehicleType(item.vehicleType), normalizeVehicleModel(item.model)],
      matchKeys: [item.city, item.vehicleType, item.route, item.model],
      vehicleType: normalizeVehicleType(item.vehicleType),
      model: normalizeVehicleModel(item.model),
      route: item.route,
      raw: item,
    }));
  });

  state.productCatalog.tickets.forEach((item, index) => {
    const adultCost = ticketAdultCost(item, getDemandSafe().startDate);
    const childCost = ticketChildCost(item, getDemandSafe().startDate);
    resources.push(makeQuoteResource({
      id: `QR-TIC-${String(index + 1).padStart(5, "0")}`,
      type: "ticket",
      city: item.city,
      name: item.scenicName,
      unit: "人",
      cost: valueOrEmpty(adultCost),
      salePrice: valueOrEmpty(adultCost),
      childCost: valueOrEmpty(childCost),
      childPrice: valueOrEmpty(childCost),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `TICKET-${index + 1}`,
      sourceCategory: "景点门票",
      status: adultCost === "" ? "待补成本" : "可用",
      tags: [item.scenicName, item.ticketType, item.type, item.freePolicy, item.remark],
      matchKeys: [item.city, item.scenicName, item.ticketType, shortTicketName(item.scenicName)],
      scenicName: item.scenicName,
      ticketType: normalizeTicketType(item.ticketType),
      raw: item,
    }));
  });

  state.productCatalog.experiences.forEach((item, index) => {
    resources.push(makeQuoteResource({
      id: `QR-EXP-${String(index + 1).padStart(5, "0")}`,
      type: "experience",
      city: item.city,
      name: `${item.experienceName} ${item.ticketType}`,
      unit: "人",
      cost: valueOrEmpty(item.adultCost),
      salePrice: valueOrEmpty(item.adultSale),
      childCost: valueOrEmpty(item.childCost),
      childPrice: valueOrEmpty(item.childSale),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `EXP-${index + 1}`,
      sourceCategory: "特色体验",
      status: item.adultCost === "" || item.adultCost == null ? "待补成本" : "可用",
      tags: [item.experienceName, item.ticketType, item.duration, item.remark],
      matchKeys: [item.city, item.experienceName, item.ticketType],
      experienceName: item.experienceName,
      ticketType: normalizeTicketType(item.ticketType),
      raw: item,
    }));
  });

  state.productCatalog.guides.forEach((item, index) => {
    const d = getDemandSafe();
    const cost = isPeakSeason(d.startDate) ? firstPresent(item.highSeasonCost, item.lowSeasonCost) : firstPresent(item.lowSeasonCost, item.highSeasonCost);
    const sale = isPeakSeason(d.startDate) ? firstPresent(item.highSeasonSale, item.lowSeasonSale) : firstPresent(item.lowSeasonSale, item.highSeasonSale);
    resources.push(makeQuoteResource({
      id: `QR-GUI-${String(index + 1).padStart(5, "0")}`,
      type: "guide",
      city: item.city,
      name: `${item.language}导游服务`,
      unit: "天",
      cost: valueOrEmpty(cost),
      salePrice: valueOrEmpty(sale),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `GUIDE-${index + 1}`,
      sourceCategory: "导游",
      status: cost === "" ? "待补成本" : "可用",
      tags: [item.language, item.needsTicket],
      matchKeys: [item.city, item.language, `${item.language}导游`],
      language: item.language,
      raw: item,
    }));
  });

  state.productCatalog.hotels.forEach((item, index) => {
    resources.push(makeQuoteResource({
      id: `QR-HOT-${String(index + 1).padStart(5, "0")}`,
      type: "hotel",
      city: item.city,
      name: item.hotelName,
      unit: "间夜",
      cost: valueOrEmpty(item.costPrice),
      salePrice: valueOrEmpty(item.salePrice),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `HOTEL-${index + 1}`,
      sourceCategory: "酒店",
      status: item.costPrice === "" || item.costPrice == null ? "待补成本" : "可用",
      tags: [item.hotelName, item.star, item.roomType, item.breakfast, item.hasAgreement, item.agreementFixed],
      matchKeys: [item.city, item.hotelName, item.star, normalizeHotelStar(item.star), item.roomType],
      star: normalizeHotelStar(item.star),
      roomType: normalizeRoomType(item.roomType),
      breakfast: item.breakfast,
      agreementFixed: item.agreementFixed,
      hasAgreement: item.hasAgreement,
      raw: item,
    }));
  });

  state.productCatalog.meals.forEach((item, index) => {
    resources.push(makeQuoteResource({
      id: `QR-MEAL-${String(index + 1).padStart(5, "0")}`,
      type: "meal",
      city: item.city,
      name: item.restaurant,
      unit: "人",
      cost: valueOrEmpty(item.costPrice),
      salePrice: valueOrEmpty(firstPresent(item.suggestedSale, item.minSale)),
      supplierName: item.supplierName || IMPORTED_PENDING_SUPPLIER,
      sourceProductId: `MEAL-${index + 1}`,
      sourceCategory: "餐",
      status: item.costPrice === "" || item.costPrice == null ? "待补成本" : "可用",
      tags: [item.cuisine, item.halal, item.restaurant, item.area],
      matchKeys: [item.city, item.cuisine, item.halal, item.restaurant, item.area],
      cuisine: item.cuisine,
      halal: item.halal,
      restaurant: item.restaurant,
      minSale: item.minSale,
      suggestedSale: item.suggestedSale,
      phone: item.phone,
      area: item.area,
      raw: item,
    }));
  });
  return resources;
}

function makeQuoteResource(resource) {
  const normalizedName = normalizeResourceText(resource.name);
  const matchKeys = unique([...(resource.matchKeys || []), ...(resource.tags || []), resource.name, normalizedName])
    .map((item) => normalizeResourceText(item))
    .filter(Boolean);
  return {
    supplierId: "",
    validFrom: IMPORT_VALID_FROM,
    validTo: IMPORT_VALID_TO,
    tags: [],
    matchKeys,
    normalizedName,
    ...resource,
    supplierName: resource.supplierName || IMPORTED_PENDING_SUPPLIER,
    normalizedName,
    matchKeys,
  };
}

function valueOrEmpty(value) {
  return value === "" || value == null ? "" : value;
}

function firstPresent(...values) {
  const found = values.find((value) => value !== "" && value != null);
  return found ?? "";
}

function getDemandSafe() {
  try {
    return getDemand();
  } catch {
    return { startDate: "", people: 0, country: "", specialNeed: "", roomTypes: [], hotelLevel: "", hotelBreakfast: "" };
  }
}

function normalizeResourceText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[（）()《》“”"'\s·•]/g, "")
    .replace(/～/g, "~")
    .trim();
}

function normalizeVehicleModel(value) {
  const text = String(value || "").replace(/\s+/g, "").replace(/车/g, "");
  if (/14|17|16|15/.test(text)) return "14座~17座";
  if (/36|38|33/.test(text)) return "36~38座";
  if (/51|55|50/.test(text)) return "51~55座";
  if (/22/.test(text)) return "22座";
  if (/9/.test(text)) return "9座";
  if (/7|8/.test(text)) return "7座";
  if (/5/.test(text)) return "5座";
  return text || "";
}

function normalizeVehicleType(value) {
  const text = String(value || "");
  if (/接送机|接机|送机|机场/.test(text)) return "接送机";
  if (/接送站|接站|送站|火车站|高铁站/.test(text)) return "接送站";
  if (/城际|周边|跨城/.test(text)) return "城际/周边";
  if (/包车|一日游|两日游|三日游|四日游|用车/.test(text)) return "包车";
  return text || "包车";
}

function normalizeHotelStar(value) {
  const text = String(value || "");
  if (/豪华/.test(text)) return "五星级/豪华型";
  if (/5|五/.test(text)) return "五星级";
  if (/4|四|舒适/.test(text)) return "四星级";
  if (/3|三/.test(text)) return "三星级";
  return text || "待补星级";
}

function normalizeRoomType(value) {
  const text = String(value || "");
  if (/双|标|大床或标间|大床或标/.test(text)) return "双床房";
  if (/大床/.test(text)) return "大床房";
  if (/三/.test(text)) return "三人间";
  if (/套/.test(text)) return "套房";
  return text || "房型待定";
}

function normalizeTicketType(value) {
  return normalizeResourceText(value || "景区门票");
}

function isPeakSeason(date) {
  const month = Number(String(date || "").slice(5, 7));
  return month >= 6 && month <= 8;
}

function ticketAdultCost(item, date) {
  if (item.agencyAdult !== "" && item.agencyAdult != null) return item.agencyAdult;
  if (isPeakSeason(date) && item.peakAdult !== "" && item.peakAdult != null) return item.peakAdult;
  if (!isPeakSeason(date) && item.offAdult !== "" && item.offAdult != null) return item.offAdult;
  return firstPresent(item.peakAdult, item.offAdult);
}

function ticketChildCost(item, date) {
  if (item.agencyDiscount !== "" && item.agencyDiscount != null) return item.agencyDiscount;
  if (isPeakSeason(date) && item.peakDiscount !== "" && item.peakDiscount != null) return item.peakDiscount;
  if (!isPeakSeason(date) && item.offDiscount !== "" && item.offDiscount != null) return item.offDiscount;
  return firstPresent(item.peakDiscount, item.offDiscount);
}

function sourceFromResource(resource, sourceType = "产品库") {
  if (!resource) return { source: "待补价", sourceType: "待补价" };
  const supplier = resource.supplierName || supplierById(resource.supplierId)?.name || IMPORTED_PENDING_SUPPLIER;
  return {
    source: `${sourceType} / ${supplier} / ${resource.name}`,
    sourceType,
    sourceResourceId: resource.id,
    sourceProductId: resource.sourceProductId,
    sourceName: resource.name,
  };
}

function resourceResult(resource, costField = "cost") {
  if (!resource) return pendingResult("待补价");
  return {
    cost: valueOrEmpty(resource[costField]),
    salePrice: valueOrEmpty(resource.salePrice),
    childCost: valueOrEmpty(resource.childCost),
    childPrice: valueOrEmpty(resource.childPrice),
    candidates: [],
    ...sourceFromResource(resource),
    resource,
  };
}

function pendingResult(source, candidates = []) {
  return {
    cost: "",
    salePrice: "",
    childCost: "",
    childPrice: "",
    source,
    sourceType: source.includes("待选择") ? "待选择资源" : "待补价",
    candidates,
    sourceResourceId: "",
    sourceProductId: "",
    sourceName: "",
  };
}

function traceFields(result, fallbackType = "") {
  const resource = result?.resource || {};
  return {
    sourceProductId: result?.sourceProductId || resource.sourceProductId || "",
    sourceResourceId: result?.sourceResourceId || resource.id || "",
    sourceName: result?.sourceName || resource.name || "",
    sourceType: result?.sourceType || fallbackType || "",
    candidates: result?.candidates || [],
  };
}

function legacyVehicleKey(model) {
  const normalized = normalizeVehicleModel(model);
  if (normalized === "14座~17座") return "14座车";
  if (normalized === "36~38座") return "33座车";
  if (normalized === "51~55座") return "55座车";
  return normalized ? `${normalized.replace(/~.*/, "座").replace(/座座$/, "座")}车` : model;
}

function withLegacyFallback(result, fallbackCost, label) {
  if (result?.cost !== "" || result?.sourceType === "待选择资源") return result;
  if (fallbackCost === "" || fallbackCost == null) return result;
  return {
    ...pendingResult(`旧标准价 / ${label}`),
    cost: fallbackCost,
    sourceType: "旧标准价",
  };
}

function candidateSummary(candidates) {
  return candidates.slice(0, 5).map((item) => item.name).join("；");
}

function activeQuoteResource(resource) {
  return resource && resource.status !== "停用" && daysUntil(resource.validTo) >= 0;
}

function sameCity(resource, city) {
  return !city || resource.city === city || resource.city === "通用";
}

function textMatchesRoute(resource, text) {
  const body = normalizeResourceText(text);
  const route = normalizeResourceText(resource.route || resource.raw?.route || resource.name);
  if (!body || !route) return false;
  const genericParts = new Set(["市区", "城区", "市内", "包车", "用车", "酒店", "景区", "机场"]);
  const parts = route.split(/[+、，,/-]/)
    .map((part) => part.trim())
    .filter((part) => part.length >= 2)
    .filter((part) => !genericParts.has(part))
    .filter((part) => !/^市区\d*小时?$/.test(part) && !/^\d+小时$/.test(part));
  return parts.some((part) => body.includes(part)) || body.includes(route);
}

function airportKeyword(text) {
  const keywords = ["首都机场", "大兴机场", "浦东", "虹桥", "萧山", "双流", "天府", "咸阳", "白云", "宝安", "机场"];
  return keywords.find((keyword) => String(text || "").includes(keyword)) || "";
}

function lookupVehicleResource({ city, vehicleType, model, text = "" }) {
  const normalizedType = normalizeVehicleType(vehicleType);
  const normalizedModel = normalizeVehicleModel(model);
  let candidates = quoteResources().filter((resource) => {
    return resource.type === "vehicle"
      && sameCity(resource, city)
      && resource.vehicleType === normalizedType
      && resource.model === normalizedModel
      && activeQuoteResource(resource);
  });
  const airport = airportKeyword(text);
  if (normalizedType === "接送机" && airport) {
    const airportMatches = candidates.filter((resource) => normalizeResourceText(resource.route).includes(normalizeResourceText(airport)));
    if (airportMatches.length) candidates = airportMatches;
  }
  const routeMatches = candidates.filter((resource) => textMatchesRoute(resource, text));
  if (routeMatches.length) candidates = routeMatches;
  if (!candidates.length) return pendingResult("待补价：未找到匹配车型资源");
  if (candidates.length > 1 && !routeMatches.length && !airport) {
    return pendingResult(`待选择资源：${candidateSummary(candidates)}`, candidates);
  }
  const selected = candidates
    .slice()
    .sort((a, b) => number(a.cost) - number(b.cost))[0];
  const result = resourceResult(selected);
  result.candidates = candidates;
  result.source = `${result.source}${candidates.length > 1 ? ` / 候选${candidates.length}条` : ""}`;
  return result;
}

function lookupGuideResource(city, language, date) {
  const candidates = quoteResources().filter((resource) => {
    return resource.type === "guide"
      && sameCity(resource, city)
      && normalizeResourceText(resource.language) === normalizeResourceText(language)
      && activeQuoteResource(resource);
  });
  if (!candidates.length) return pendingResult("待补价：未找到导游资源");
  const selected = candidates[0];
  const raw = selected.raw || {};
  const cost = isPeakSeason(date) ? firstPresent(raw.highSeasonCost, raw.lowSeasonCost, selected.cost) : firstPresent(raw.lowSeasonCost, raw.highSeasonCost, selected.cost);
  return { ...resourceResult(selected), cost };
}

function lookupHotelResource({ city, star, roomType }) {
  const normalizedStar = normalizeHotelStar(star);
  const normalizedRoom = normalizeRoomType(roomType);
  let candidates = quoteResources().filter((resource) => {
    const starHit = resource.star === normalizedStar || (normalizedStar === "五星级/豪华型" && resource.star.includes("五星"));
    return resource.type === "hotel" && sameCity(resource, city) && starHit && activeQuoteResource(resource);
  });
  const roomMatches = candidates.filter((resource) => resource.roomType === normalizedRoom || resource.raw?.roomType?.includes(roomType));
  if (roomMatches.length) candidates = roomMatches;
  if (!candidates.length) return pendingResult("待补价：未找到匹配酒店资源");
  const selected = candidates.slice().sort((a, b) => number(a.cost) - number(b.cost))[0];
  const result = resourceResult(selected);
  result.candidates = candidates;
  result.source = `${result.source} / ${selected.raw?.star || normalizedStar} / ${selected.raw?.roomType || roomType}${candidates.length > 1 ? ` / 候选${candidates.length}家` : ""}`;
  return result;
}

function needHalalMeal(d) {
  const text = `${d.country || ""} ${d.specialNeed || ""}`;
  return /清真|穆斯林|阿联酋|沙特|卡塔尔|科威特|阿曼|巴林|马来|印尼|中东|halal|muslim/i.test(text);
}

function lookupMealResource({ city, meal, demand }) {
  if (meal === "早餐") {
    return {
      ...pendingResult("旧标准价 / 早餐"),
      cost: resources.meals.早餐,
      sourceType: "旧标准价",
    };
  }
  let candidates = quoteResources().filter((resource) => resource.type === "meal" && sameCity(resource, city));
  if (needHalalMeal(demand)) {
    const halal = candidates.filter((resource) => resource.halal === "是");
    if (halal.length) candidates = halal;
  }
  if (!candidates.length) {
    return {
      ...pendingResult("旧标准价 / 餐费兜底"),
      cost: resources.meals[meal] || "",
      sourceType: "旧标准价",
    };
  }
  const withCost = candidates.filter((resource) => resource.cost !== "" && resource.cost != null);
  const selected = (withCost.length ? withCost : candidates).slice().sort((a, b) => number(a.cost || a.salePrice) - number(b.cost || b.salePrice))[0];
  const result = resourceResult(selected);
  result.candidates = candidates;
  if (selected.cost === "" || selected.cost == null) {
    result.source = `待补成本 / ${selected.supplierName} / ${selected.name}${selected.salePrice ? ` / 卖价参考${money(selected.salePrice)}` : ""}`;
    result.sourceType = "待补价";
  } else {
    result.source = `${result.source}${needHalalMeal(demand) ? " / 清真优先" : ""}${candidates.length > 1 ? ` / 候选${candidates.length}家` : ""}`;
  }
  return result;
}

function lookupTicketResource(name, city, date, ticketType = "景区门票") {
  let candidates = quoteResources().filter((resource) => {
    const sameScenic = sameTicketName(resource.scenicName || resource.name, name) || sameTicketName(shortTicketName(resource.scenicName || resource.name), name);
    return resource.type === "ticket" && sameCity(resource, city) && sameScenic && activeQuoteResource(resource);
  });
  if (!candidates.length) return null;
  const normalizedRequestedType = normalizeTicketType(ticketType);
  const exactType = candidates.filter((resource) => resource.ticketType === normalizedRequestedType);
  if (exactType.length) candidates = exactType;
  if (!exactType.length && !normalizeResourceText(name).includes(normalizeResourceText(ticketType))) {
    const mainTicket = candidates.filter((resource) => /景区门票|门票/.test(resource.raw?.ticketType || "") && !/馆|索道|缆车|夜场|演出|优速通/.test(resource.raw?.ticketType || ""));
    if (mainTicket.length) candidates = mainTicket;
  }
  const selected = candidates[0];
  const adultCost = ticketAdultCost(selected.raw || {}, date);
  const childCost = ticketChildCost(selected.raw || {}, date);
  return {
    ...resourceResult(selected),
    cost: valueOrEmpty(adultCost),
    childCost: valueOrEmpty(childCost),
    candidates,
    source: `${sourceFromResource(selected).source} / ${selected.raw?.ticketType || ticketType}${candidates.length > 1 ? ` / 候选${candidates.length}个票种` : ""}`,
  };
}

function lookupExperienceResource({ city, name, ticketType }) {
  const candidates = quoteResources().filter((resource) => {
    return resource.type === "experience"
      && sameCity(resource, city)
      && sameTicketName(resource.experienceName || resource.name, name)
      && (!ticketType || resource.ticketType === normalizeTicketType(ticketType))
      && activeQuoteResource(resource);
  });
  if (!candidates.length) return pendingResult("待补价：未找到体验资源");
  return resourceResult(candidates[0]);
}

function routeProductById(id) {
  return state.productCatalog.routes.find((route) => route.routeProductId === id || route.code === id);
}

function selectedRouteProduct() {
  return routeProductById(state.selectedRouteProductId);
}

function routeCostTier(route, people) {
  const count = number(people);
  const tiers = Object.entries(route?.costTiers || {});
  for (const [label, value] of tiers) {
    const numbers = label.match(/\d+/g)?.map(Number) || [];
    if (!numbers.length) continue;
    const [min, max = min] = numbers;
    if (count >= min && count <= max && value !== "" && value != null) return { label, unitCost: value, totalCost: number(value) * count };
  }
  return { label: "待询价", unitCost: "", totalCost: "" };
}

function buildImportQualityReport() {
  const categories = {
    routes: { label: "线路产品", items: state.productCatalog.routes, resources: [] },
    vehicles: { label: "用车", items: state.productCatalog.vehicles, resources: quoteResourcesRaw("vehicle") },
    experiences: { label: "特色体验", items: state.productCatalog.experiences, resources: quoteResourcesRaw("experience") },
    tickets: { label: "景点门票", items: state.productCatalog.tickets, resources: quoteResourcesRaw("ticket") },
    guides: { label: "导游", items: state.productCatalog.guides, resources: quoteResourcesRaw("guide") },
    hotels: { label: "酒店", items: state.productCatalog.hotels, resources: quoteResourcesRaw("hotel") },
    meals: { label: "餐", items: state.productCatalog.meals, resources: quoteResourcesRaw("meal") },
  };
  const rows = Object.entries(categories).map(([key, item]) => qualityRow(key, item.label, item.items, item.resources));
  return { rows, generatedAt: "2026-06-21" };
}

function quoteResourcesRaw(type) {
  return (state.quoteResources || []).filter((resource) => resource.type === type);
}

function qualityRow(key, label, items, resources) {
  if (key === "routes") {
    const quoteableRoutes = items.filter((item) => Object.values(item.costTiers || {}).some((value) => value !== "" && value != null)).length;
    const missingCost = items.length - quoteableRoutes;
    return {
      key,
      label,
      imported: items.length,
      quoteable: quoteableRoutes,
      missingCost,
      missingChild: 0,
      missingSupplier: 0,
      duplicateCount: duplicateResourceCount(items.map((item) => ({
        type: "route",
        city: item.city,
        normalizedName: normalizeResourceText(`${item.code}-${item.name}`),
      }))),
      notQuoteable: missingCost,
      keyMissing: qualityMissingFields(key, items),
      status: missingCost ? "可展示但需补成本" : "可直接报价",
    };
  }
  const missingCost = resources.filter((resource) => resource.cost === "" || resource.cost == null).length;
  const missingChild = resources.filter((resource) => ["ticket", "experience"].includes(resource.type) && (resource.childCost === "" || resource.childCost == null)).length;
  const missingSupplier = resources.filter((resource) => !resource.supplierId && resource.supplierName === IMPORTED_PENDING_SUPPLIER).length;
  const duplicateCount = duplicateResourceCount(resources);
  const keyMissing = qualityMissingFields(key, items);
  const quoteable = resources.filter((resource) => resource.status === "可用" && resource.cost !== "" && resource.cost != null).length;
  const notQuoteable = Math.max(items.length - quoteable, 0);
  return {
    key,
    label,
    imported: items.length,
    quoteable,
    missingCost,
    missingChild,
    missingSupplier,
    duplicateCount,
    notQuoteable,
    keyMissing,
    status: quoteable === items.length ? "可直接报价" : quoteable > 0 ? "可展示但需补成本" : "不可报价",
  };
}

function duplicateResourceCount(resources) {
  const seen = new Set();
  let duplicates = 0;
  resources.forEach((resource) => {
    const key = [resource.type, resource.city, resource.normalizedName, resource.ticketType, resource.model, resource.roomType, resource.vehicleType].join("|");
    if (seen.has(key)) duplicates += 1;
    seen.add(key);
  });
  return duplicates;
}

function qualityMissingFields(key, items) {
  const rules = {
    routes: ["code", "city", "days", "name"],
    vehicles: ["city", "vehicleType", "route", "model"],
    experiences: ["city", "experienceName", "ticketType"],
    tickets: ["city", "scenicName", "ticketType"],
    guides: ["city", "language"],
    hotels: ["city", "hotelName", "star", "roomType"],
    meals: ["city", "restaurant"],
  }[key] || [];
  return items
    .map((item, index) => ({ index: index + 1, missing: rules.filter((field) => !item[field]) }))
    .filter((item) => item.missing.length)
    .slice(0, 20);
}

function filteredProductCatalogItems(category) {
  const f = state.resourceFilters;
  return productCatalogItems(category).filter((item) => {
    const haystack = Object.values(item).join(" ").toLowerCase();
    const mainHit = !f.status || productMainFilterValue(category, item) === f.status;
    const columnHit = productColumnFilterHit(category, item);
    return (!f.search || haystack.includes(f.search.toLowerCase()))
      && (!f.city || String(item.city || "").includes(f.city))
      && mainHit
      && columnHit;
  });
}

function productColumnFilterHit(category, item) {
  const filter = state.productColumnFilter || {};
  if (!filter.column || !filter.value) return true;
  const map = productColumnKeyMap(category);
  const key = map[filter.column];
  if (!key) return true;
  return String(item[key] ?? "").toLowerCase().includes(filter.value.toLowerCase());
}

function productColumnKeyMap(category) {
  if (category === "景点门票") {
    return { 城市: "city", 景点名称: "scenicName", 类型: "type", 票种: "ticketType", 免费政策: "freePolicy", 备注: "remark" };
  }
  if (category === "特色体验") {
    return { 城市: "city", 体验名称: "experienceName", 票种: "ticketType", 体验时间: "duration", 体验介绍信息: "intro", 备注: "remark" };
  }
  return {};
}

function productMainFilterValue(category, item) {
  if (category === "线路产品") return item.productType;
  if (category === "用车") return item.vehicleType;
  if (category === "导游") return item.language;
  if (category === "酒店") return item.star;
  if (category === "餐") return item.halal;
  if (category === "景点门票") return item.type;
  return item.city;
}

function productListHint(category) {
  const hints = {
    线路产品: "产品详情可进入对应报价项目详情，后续可承接行程、报价和客人方案。",
    用车: "卖价和成本价可联动用车供应商，操作可跳转供应商列表。",
    导游: "按城市和语种维护旺季、淡季与超时费。",
    酒店: "按城市、星级、房型和协议价状态维护酒店资源。",
    餐: "按城市、菜品和是否清真维护餐厅资源。",
    景点门票: "按照门票表头列展示，可用上方筛选快速定位。",
    特色体验: "按照特色体验表头列展示，操作可进入体验供应商列表。",
  };
  return hints[category] || "按当前二级目录展示对应产品字段。";
}

function renderProductStats(category) {
  const items = productCatalogItems(category);
  if (category === "景点门票" || category === "特色体验") return "";
  if (category === "线路产品") {
    const cityCounts = countBy(items.flatMap((item) => item.city.split("、")));
    return [
      ["线路总数", `${items.length} 条`],
      ["一日游", `${items.filter((item) => item.productType === "一日游").length} 条`],
      ["单城多日", `${items.filter((item) => item.productType === "单城多日游").length} 条`],
      ["多城多日", `${items.filter((item) => item.productType === "多城多日游").length} 条`],
      ["城市分布", countText(cityCounts)],
    ].map(statTile).join("");
  }
  if (category === "用车") {
    const supplierCityCounts = countBy(state.suppliers.filter((item) => item.category === "用车").flatMap((item) => item.cities));
    const modelCounts = countBy(items.map((item) => item.model));
    return [
      ["经营车队", countText(supplierCityCounts)],
      ["私家车", "0 辆"],
      ["车型数量", countText(modelCounts)],
      ["服务类型", countText(countBy(items.map((item) => item.vehicleType)))],
    ].map(statTile).join("");
  }
  if (category === "导游") {
    return [
      ["城市分布", countText(countBy(items.map((item) => item.city)))],
      ["语种分布", countText(countBy(items.map((item) => item.language)))],
      ["导游报价", `${items.length} 条`],
    ].map(statTile).join("");
  }
  if (category === "酒店") {
    return [
      ["城市分布", countText(countBy(items.map((item) => item.city)))],
      ["酒店等级", countText(countBy(items.map((item) => item.star)))],
      ["房型统计", countText(countBy(items.map((item) => item.roomType)))],
      ["酒店数量", `${items.length} 家`],
    ].map(statTile).join("");
  }
  if (category === "餐") {
    return [
      ["城市分布", countText(countBy(items.map((item) => item.city)))],
      ["菜品分布", countText(countBy(items.map((item) => item.cuisine)))],
      ["清真餐厅", `${items.filter((item) => item.halal === "是").length} 家`],
      ["餐厅数量", `${items.length} 家`],
    ].map(statTile).join("");
  }
  return "";
}

function statTile([label, value]) {
  return `<div class="stat-tile"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`;
}

function countBy(values) {
  return values.filter(Boolean).reduce((acc, value) => {
    acc[value] = (acc[value] || 0) + 1;
    return acc;
  }, {});
}

function countText(counts) {
  const text = Object.entries(counts).map(([key, value]) => `${key} ${value}`).join(" / ");
  return text || "-";
}

function renderCatalogExtraFilters(category) {
  if (category !== "景点门票" && category !== "特色体验") return "";
  const fields = Object.keys(productColumnKeyMap(category));
  return `<div class="table-filter-bar">
    <label>表头字段<select id="productColumnSelect"><option value="">选择字段</option>${fields.map((field) => `<option ${state.productColumnFilter.column === field ? "selected" : ""}>${field}</option>`).join("")}</select></label>
    <label>筛选内容<input id="productColumnValue" value="${escapeHtml(state.productColumnFilter.value || "")}" placeholder="输入关键词" /></label>
    <button class="secondary-btn" id="clearProductColumnFilter">清空表头筛选</button>
  </div>`;
}

