function useProductInQuote(id) {
  const product = state.products.find((item) => item.id === id);
  if (!product) return;
  switchModule("quote");
  alert(`已选择产品「${product.name}」。正式版会把该产品下挂的供应商成本和手动成本带入报价明细；当前原型仍会按行程、城市和服务项自动匹配成本。`);
}

function useResourceInQuote(id) {
  const item = state.resourceItems.find((resource) => resource.id === id);
  if (!item) return;
  state.resourceFilters.type = item.type;
  state.resourceFilters.city = item.city === "通用" ? "" : item.city;
  switchModule("quote");
  alert(`已确认资源「${item.name}」会被报价模块自动匹配。生成报价时将优先调用供应商「${supplierById(item.supplierId)?.name || item.supplierName || IMPORTED_PENDING_SUPPLIER}」的成本。`);
}

function supplierById(id) {
  return state.suppliers.find((supplier) => supplier.id === id);
}

function resourceStatusText(item) {
  if (item.status !== "可用") return item.status;
  return daysUntil(item.validTo) <= 45 ? "即将过期" : "可用";
}

function resourceStatusClass(item) {
  const status = resourceStatusText(item);
  if (status === "可用") return "ok";
  if (status === "即将过期" || status === "待确认") return "warn";
  return "danger";
}

function daysUntil(date) {
  return Math.round((dateValue(date) - dateValue("2026-06-18")) / 86400000);
}

function openProject(id) {
  state.currentProjectId = id;
  const project = state.projects.find((item) => item.id === id);
  if (project) {
    $("#projectId").textContent = project.id;
    $("#clientName").value = project.name;
    if ($("#actualCustomerName")) $("#actualCustomerName").value = project.name.split(/\s+/)[0] || project.name;
    $("#clientAccount").value = project.account || "";
    $("#clientType").value = project.userType || "直客";
    $("#clientCountry").value = project.country || "";
    $("#source").value = project.source || "WhatsApp";
    const followMap = { 报价中: "需求确认中", 价格已报但未成交: "已发报价", 已成交待操作: "已成交", 已操作待服务: "已成交", 已服务待评价: "已成交" };
    $("#followStatus").value = followMap[project.status] || project.status;
    $("#cities").value = project.cities;
    $("#startDate").value = project.serviceStart || project.startDate || "2026-07-01";
    $("#serviceDays").value = project.days || 1;
    $("#adults").value = project.guests ? Math.max(project.guests - 1, 0) : 0;
    $("#children").value = project.guests ? 1 : 0;
  }
  if (!state.itinerary.length) handleLoadHistory();
  showProjectDetail();
  updateProjectTitle();
}

function updateCurrentProject(status) {
  let project = state.projects.find((item) => item.id === state.currentProjectId);
  const d = getDemand();
  const totals = activeQuote()?.data ? calcTotals() : { sell: 0 };
  if (!project) {
    project = { id: $("#projectId").textContent, owner: $("#owner").value || "定制师 A", source: $("#source").value || "WhatsApp" };
    state.projects.unshift(project);
    state.currentProjectId = project.id;
  }
  project.name = d.clientName;
  project.account = d.account;
  project.userType = d.userType;
  project.country = d.country;
  project.status = status || project.status || "需求确认中";
  project.source = $("#source").value;
  project.owner = $("#owner").value;
  project.cities = d.cities.join("、") || "待定";
  project.serviceStart = d.startDate;
  project.days = d.serviceDays;
  project.guests = d.people;
  project.amount = Math.round(totals.sell || 0);
  project.statusUpdatedDate = "2026-06-18";
  project.createdDate = project.createdDate || "2026-06-18";
  renderProjectDashboard();
}

