function writeAcceptanceProbe() {
  const compactResource = (resource) => ({
    name: resource.name,
    model: resource.model,
    vehicleType: resource.vehicleType,
    star: resource.star,
    roomType: resource.roomType,
    halal: resource.halal,
    ticketType: resource.raw?.ticketType || resource.ticketType,
  });
  const vehicle14 = lookupVehicleResource({ city: "北京", vehicleType: "包车", model: "14座车", text: "北京市区包车" });
  const vehicle7 = lookupVehicleResource({ city: "北京", vehicleType: "包车", model: "7座车", text: "北京市区包车" });
  const hotel4 = lookupHotelResource({ city: "北京", star: "4星舒适型", roomType: "双床房" });
  const mealHalal = lookupMealResource({ city: "北京", meal: "午餐", demand: { country: "阿联酋", specialNeed: "清真" } });
  const ticket = lookupTicketCost("故宫博物院", "北京", "2026-07-01", "景区门票");
  const probe = {
    counts: {
      routes: state.productCatalog.routes.length,
      vehicles: state.productCatalog.vehicles.length,
      experiences: state.productCatalog.experiences.length,
      tickets: state.productCatalog.tickets.length,
      guides: state.productCatalog.guides.length,
      hotels: state.productCatalog.hotels.length,
      transports: state.productCatalog.transports?.length || 0,
      meals: state.productCatalog.meals.length,
    },
    quoteResourceCounts: state.quoteResources.reduce((acc, item) => {
      acc[item.type] = (acc[item.type] || 0) + 1;
      return acc;
    }, {}),
    vehicle14: { sourceType: vehicle14.sourceType, source: vehicle14.source, candidates: (vehicle14.candidates || []).slice(0, 8).map(compactResource) },
    vehicle7: { sourceType: vehicle7.sourceType, source: vehicle7.source, candidates: (vehicle7.candidates || []).slice(0, 8).map(compactResource) },
    hotel4: { cost: hotel4.cost, sourceName: hotel4.sourceName, source: hotel4.source, candidates: (hotel4.candidates || []).slice(0, 8).map(compactResource) },
    mealHalal: { cost: mealHalal.cost, source: mealHalal.source, candidates: (mealHalal.candidates || []).slice(0, 8).map(compactResource) },
    ticket: { adultCost: ticket.adultCost, childCost: ticket.childCost, source: ticket.source, ticketType: ticket.ticketType, candidates: (ticket.candidates || []).slice(0, 8).map(compactResource) },
    uniqueRouteIds: new Set(state.productCatalog.routes.map((route) => route.routeProductId)).size,
    firstRouteProjectId: state.productCatalog.routes[0]?.projectId || "",
    qualityRows: state.importQuality.rows.map((row) => ({
      label: row.label,
      imported: row.imported,
      quoteable: row.quoteable,
      missingCost: row.missingCost,
      missingChild: row.missingChild,
      missingSupplier: row.missingSupplier,
      duplicateCount: row.duplicateCount,
      notQuoteable: row.notQuoteable,
    })),
  };
  const node = document.getElementById("workbenchAcceptanceProbe") || document.createElement("script");
  node.id = "workbenchAcceptanceProbe";
  node.type = "application/json";
  node.textContent = JSON.stringify(probe);
  if (!node.parentNode) document.body.appendChild(node);
}

init();
writeAcceptanceProbe();
